import{db}from './database.js';function createProjectCard(project,isPageAllProjects=!1){let statusClass=project.status==='ativo'?'ativo':'planejamento';let iconClass=project.icon||'fa-palette';const buttonHtml=isPageAllProjects?`<a href="/cadastro" class="btn btn-primary btn-small nav-link">Ser Voluntário</a>`:`<a href="/projetos" class="btn btn-primary btn-small nav-link">Ver Projetos <i class="fa-solid fa-arrow-right"></i></a>`;const authorHtml=`<span>Por: <strong>${project.author}</strong></span>`;return `
    <div class="project-card" data-title="${project.title}" data-category="${project.category}">
        <div class="project-image">
            <picture>
                <source srcset="${project.imgWebp}" type="image/webp">
                <img src="${project.imgSrc}" alt="${project.alt}">
            </picture>
            <span class="project-tag-status ${statusClass}">${project.status}</span>
            <span class="project-tag-category"><i class="fa-solid ${iconClass}"></i> ${project.category}</span>
        </div>
        <div class="project-content">
            <h3>${project.title}</h3>
            <p>${project.description}</p>
            <div class="progress-bar">
                <span class="progress-label">${project.progress}%</span>
                <div class="progress" style="width: ${project.progress}%;"></div>
            </div>
            <div class="project-meta-compact">
                <span><strong>Arrecadado:</strong> ${project.raised}</span>
                <span><strong>Meta:</strong> ${project.goal}</span>
            </div>
            <div class="project-meta-icons">
                <span><i class="fa-solid fa-users"></i> ${project.volunteers} voluntários</span>
                <span><i class="fa-solid fa-calendar-check"></i> ${project.endDate}</span>
            </div>
            <hr>
            <div class="project-footer">
                ${authorHtml}
                ${buttonHtml}
            </div>
        </div>
    </div>
    `}
function createTestimonialCard(testimonial){return `
    <div class="testimonial-card">
        <i class="fa-solid fa-quote-left"></i>
        <p>"${testimonial.quote}"</p>
        <div class="author">
            <picture>
                <source srcset="${testimonial.imgWebp}" type="image/webp">
                <img src="${testimonial.imgSrc}" alt="${testimonial.author}">
            </picture>
            <div>
                <strong>${testimonial.author}</strong>
                <span>${testimonial.role}</span>
            </div>
        </div>
    </div>
    `}
export function initMenu(){const menuToggle=document.querySelector('.menu-toggle');const navLinks=document.querySelector('.nav-links');const dropdown=document.querySelector('.dropdown');if(!menuToggle||!navLinks||!dropdown){console.warn("Elementos do menu não encontrados. O menu.js não será inicializado.");return}
const dropdownMenu=dropdown.querySelector('.dropdown-menu');const dropdownLink=dropdown.querySelector('a');if(!dropdownLink||!dropdownMenu){console.warn("Dropdown do menu não encontrado.");return}
menuToggle.addEventListener('click',()=>{navLinks.classList.toggle('show')});dropdown.addEventListener('click',(e)=>{if(window.innerWidth<=992){const isMainLink=e.target===dropdownLink;const isSubLink=e.target.closest('.dropdown-menu a');if(isMainLink)return;if(isSubLink)return;e.preventDefault();dropdownMenu.classList.toggle('show')}});navLinks.addEventListener('click',(e)=>{if(e.target.closest('a')){navLinks.classList.remove('show')}});const desktopDropdownButton=document.getElementById('projetos-menu-button');const desktopDropdownMenu=document.getElementById('projetos-menu');if(desktopDropdownButton&&desktopDropdownMenu){const desktopDropdownItems=desktopDropdownMenu.querySelectorAll('a.nav-link');const toggleMenu=(shouldOpen)=>{const isExpanded=shouldOpen;desktopDropdownButton.setAttribute('aria-expanded',isExpanded);desktopDropdownButton.parentElement.classList.toggle('show',isExpanded)};desktopDropdownButton.addEventListener('click',(e)=>{e.preventDefault();e.stopPropagation();const isExpanded=desktopDropdownButton.getAttribute('aria-expanded')==='true';toggleMenu(!isExpanded)});desktopDropdownButton.addEventListener('keydown',(e)=>{if(e.key==='Enter'||e.key===' '||e.key==='ArrowDown'){e.preventDefault();e.stopPropagation();toggleMenu(!0);if(desktopDropdownItems.length>0)desktopDropdownItems[0].focus();}
if(e.key==='ArrowUp'){e.preventDefault();toggleMenu(!1)}
if(e.key==='Escape'){toggleMenu(!1);desktopDropdownButton.focus()}});desktopDropdownItems.forEach((item,index)=>{item.addEventListener('keydown',(e)=>{if(e.key==='ArrowDown'){e.preventDefault();if(index<desktopDropdownItems.length-1){desktopDropdownItems[index+1].focus()}}
if(e.key==='ArrowUp'){e.preventDefault();if(index>0){desktopDropdownItems[index-1].focus()}else{desktopDropdownButton.focus();toggleMenu(!1)}}
if(e.key==='Escape'){toggleMenu(!1);desktopDropdownButton.focus()}
if(e.key==='Tab'&&!e.shiftKey&&index===desktopDropdownItems.length-1){toggleMenu(!1)}})});document.addEventListener('click',(e)=>{if(!dropdown.contains(e.target)){toggleMenu(!1)}})}}
export function initCarousel(){const track=document.querySelector('.carousel-track');if(!track)return;const slides=Array.from(track.children);if(slides.length===0)return;const nextButton=document.querySelector('.carousel-btn.next');const prevButton=document.querySelector('.carousel-btn.prev');let currentIndex=0;function updateCarousel(){const width=slides[0].getBoundingClientRect().width;if(width===0)return;track.style.transform=`translateX(-${currentIndex * width}px)`}
nextButton.addEventListener('click',()=>{currentIndex=(currentIndex+1)%slides.length;updateCarousel()});prevButton.addEventListener('click',()=>{currentIndex=(currentIndex-1+slides.length)%slides.length;updateCarousel()});window.addEventListener('resize',updateCarousel);setInterval(()=>{currentIndex=(currentIndex+1)%slides.length;updateCarousel()},5000);updateCarousel()}
export function initFilter(){const searchInput=document.getElementById('searchInput');const projectCards=document.querySelectorAll('.projects-grid-page .project-card');const projectCountSpan=document.getElementById('projectCount');const noResultsMessage=document.getElementById('noResultsMessage');const filterMessage=document.getElementById('activeFilterMessage');const filterText=document.getElementById('filterText');const clearFilterBtn=document.getElementById('clearFilterBtn');if(projectCards.length===0||!projectCountSpan||!noResultsMessage){console.warn("Elementos do filtro não encontrados. initFilter() não será executado.");return}
function filterProjects(){const searchTerm=(searchInput?.value||'').toLowerCase().trim();const urlParams=new URLSearchParams(window.location.search);const categoriaParam=urlParams.get('categoria');const categoriaFiltro=categoriaParam?categoriaParam.toLowerCase().replace('%20',' '):null;let count=0;projectCards.forEach(card=>{const title=(card.dataset.title||'').toLowerCase();const description=card.querySelector('.project-content p')?.textContent.toLowerCase()||'';const category=(card.dataset.category||'').toLowerCase();const matchesSearch=title.includes(searchTerm)||description.includes(searchTerm);const matchesCategory=categoriaFiltro?category.includes(categoriaFiltro):!0;if(matchesSearch&&matchesCategory){card.style.display='block';count++}else{card.style.display='none'}});projectCountSpan.textContent=`${count} projeto${count !== 1 ? 's' : ''} encontrado${count !== 1 ? 's' : ''}`;noResultsMessage.style.display=count===0?'block':'none';if(categoriaParam&&filterMessage&&filterText){filterMessage.style.display='flex';filterText.innerHTML=`🔍 Mostrando projetos da categoria <strong>${categoriaParam}</strong>`}else if(filterMessage){filterMessage.style.display='none'}}
filterProjects();if(clearFilterBtn){clearFilterBtn.addEventListener('click',()=>{const url=new URL(window.location.href);url.searchParams.delete('categoria');window.history.pushState({},'',url);if(filterMessage)filterMessage.style.display='none';filterProjects()})}
if(searchInput){searchInput.addEventListener('keyup',filterProjects)}}
export function initCadastroForm(navigate){const form=document.getElementById("volunteerForm");if(!form)return;const nomeInput=document.getElementById("nome");const cpfInput=document.getElementById("cpf");const telefoneInput=document.getElementById("telefone");const cepInput=document.getElementById("cep");const cidadeInput=document.getElementById("cidade");const maskCPF=(value)=>value.replace(/\D/g,"").replace(/(\d{3})(\d)/,"$1.$2").replace(/(\d{3})(\d)/,"$1.$2").replace(/(\d{3})(\d{1,2})$/,"$1-$2");const maskTelefone=(value)=>value.replace(/\D/g,"").replace(/(\d{2})(\d)/,"($1) $2").replace(/(\d{5})(\d)/,"$1-$2");const maskCEP=(value)=>value.replace(/\D/g,"").replace(/(\d{5})(\d)/,"$1-$2");cpfInput.addEventListener("input",(e)=>(e.target.value=maskCPF(e.target.value)));telefoneInput.addEventListener("input",(e)=>(e.target.value=maskTelefone(e.target.value)));cepInput.addEventListener("input",(e)=>(e.target.value=maskCEP(e.target.value)));nomeInput.addEventListener("input",(e)=>{e.target.value=e.target.value.replace(/[^A-Za-zÀ-ÖØ-öø-ÿ\s]/g,"")});cidadeInput.addEventListener("input",(e)=>{e.target.value=e.target.value.replace(/[^A-Za-zÀ-ÖØ-öø-ÿ\s]/g,"")});const areaCheckboxes=document.querySelectorAll('input[name="areaInteresse"]');const areaError=document.getElementById("areaError");const motivacaoInput=document.getElementById("motivacao");const motivacaoCounter=document.getElementById("motivacaoCounter");const motivacaoError=document.getElementById("motivacaoError");const habilidadeCheckboxes=document.querySelectorAll('input[name="habilidade"]');const habilidadeError=document.getElementById("habilidadeError");const diasCheckboxes=document.querySelectorAll('input[name="dias"]');const diasError=document.getElementById("diasError");habilidadeCheckboxes.forEach(cb=>cb.addEventListener('change',()=>{habilidadeError.style.display='none'}));diasCheckboxes.forEach(cb=>cb.addEventListener('change',()=>{diasError.style.display='none'}));motivacaoInput.addEventListener("input",()=>{motivacaoCounter.textContent=`${motivacaoInput.value.length}/300 caracteres`;motivacaoInput.classList.remove("error");motivacaoError.style.display="none"});form.querySelectorAll("input, select, textarea").forEach((input)=>{input.addEventListener("input",()=>{input.classList.remove("error");const errorSpan=document.getElementById(input.id+'Error');if(errorSpan){errorSpan.style.display="none"}})});areaCheckboxes.forEach(cb=>cb.addEventListener('change',()=>{areaError.style.display='none';document.querySelectorAll('.card-checkbox-group.error').forEach(c=>c.classList.remove('error'))}));const nextButtons=document.querySelectorAll(".btn-next");const prevButtons=document.querySelectorAll(".btn-prev");const steps=document.querySelectorAll(".form-step");const stepIndicators=document.querySelectorAll(".stepper li");let currentStep=0;const showStep=(index)=>{steps.forEach((s,i)=>s.classList.toggle("active",i===index));stepIndicators.forEach((li,i)=>{li.classList.toggle("active",i<=index);li.removeAttribute('aria-current');if(i===index){li.setAttribute('aria-current','step')}});currentStep=index;const novaEtapa=steps[index];const novoTitulo=novaEtapa.querySelector('h3');if(novoTitulo){novoTitulo.setAttribute('tabindex','-1');novoTitulo.focus()}};const validateStep=(stepIndex)=>{let valid=!0;const stepInputs=steps[stepIndex].querySelectorAll("input[required], select[required], textarea[required]");stepInputs.forEach((input)=>{const errorSpan=document.getElementById(input.id+'Error');if(!input.checkValidity()){input.classList.add("error");if(errorSpan){errorSpan.style.display="block"}
valid=!1}else{input.classList.remove("error");if(errorSpan){errorSpan.style.display="none"}}});if(stepIndex===2){let habilidadeChecked=!1;habilidadeCheckboxes.forEach((cb)=>{if(cb.checked)habilidadeChecked=!0});if(!habilidadeChecked){habilidadeError.style.display="block";valid=!1}else{habilidadeError.style.display="none"}
let diaChecked=!1;diasCheckboxes.forEach((cb)=>{if(cb.checked)diaChecked=!0});if(!diaChecked){diasError.style.display="block";valid=!1}else{diasError.style.display="none"}}
if(stepIndex===3){let anyChecked=!1;areaCheckboxes.forEach((cb)=>{if(cb.checked)anyChecked=!0});if(!anyChecked){areaError.style.display="block";document.querySelectorAll('label[for^="area-"]').forEach(label=>{label.closest('.card-checkbox-group').classList.add('error')});valid=!1}else{areaError.style.display="none"}
if(!motivacaoInput.value.trim()){motivacaoInput.classList.add("error");document.getElementById("motivacaoError").style.display="block";valid=!1}else{document.getElementById("motivacaoError").style.display="none"}}
if(!valid){const firstError=form.querySelector('.error');if(firstError){if(firstError.tagName==='INPUT'||firstError.tagName==='SELECT'||firstError.tagName==='TEXTAREA'){firstError.focus()}else{const fieldset=firstError.closest('fieldset');if(fieldset){fieldset.querySelector('input[type="checkbox"]').focus()}}}}
return valid};nextButtons.forEach((btn)=>{btn.addEventListener("click",()=>{if(validateStep(currentStep)){currentStep++;if(currentStep<steps.length){showStep(currentStep)}}})});prevButtons.forEach((btn)=>{btn.addEventListener("click",()=>{currentStep--;if(currentStep>=0){showStep(currentStep)}})});form.addEventListener("submit",function(e){e.preventDefault();if(validateStep(currentStep)){navigate('/cadastro-sucesso')}});showStep(0)}
export function initDoacaoForm(){const form=document.getElementById("donation-form");if(!form)return;const msg=document.getElementById("mensagem-doacao");const pixInfo=document.getElementById("pix-info");const transfInfo=document.getElementById("transferencia-info");form.addEventListener("change",(e)=>{if(e.target.name==="pagamento"){pixInfo.classList.toggle("hidden",e.target.value!=="pix");transfInfo.classList.toggle("hidden",e.target.value!=="transferencia")}});form.addEventListener("submit",(e)=>{e.preventDefault();const valor=document.getElementById("valor").value;const projetoSelect=document.getElementById("projeto");const projeto=projetoSelect.options[projetoSelect.selectedIndex].text;const pagamentoInput=form.querySelector('input[name="pagamento"]:checked');if(!pagamentoInput){msg.innerHTML=`Por favor, selecione um método de pagamento.`;msg.style.color="var(--color-secondary)";return}
const pagamento=pagamentoInput.value;msg.innerHTML=`💚 Obrigado por apoiar o projeto <strong>${projeto}</strong> com <strong>R$ ${valor}</strong> via <strong>${pagamento.toUpperCase()}</strong>!`;form.reset();pixInfo.classList.add("hidden");transfInfo.classList.add("hidden")})}
export function initContatoForm(){const form=document.getElementById('contactForm');if(!form)return;const nomeInput=document.getElementById('nome');const emailInput=document.getElementById('email');if(nomeInput){nomeInput.value=localStorage.getItem('contactName')||'';nomeInput.addEventListener('input',(e)=>{localStorage.setItem('contactName',e.target.value)})}
if(emailInput){emailInput.value=localStorage.getItem('contactEmail')||'';emailInput.addEventListener('input',(e)=>{localStorage.setItem('contactEmail',e.target.value)})}
form.addEventListener('submit',(e)=>{e.preventDefault();const nome=nomeInput.value;const email=emailInput.value;const assunto=document.getElementById('assunto').value;const mensagem=document.getElementById('mensagem').value;if(nome&&email&&assunto&&mensagem){alert(`Obrigado, ${nome}! Sua mensagem foi enviada com sucesso.`);form.reset();localStorage.removeItem('contactName');localStorage.removeItem('contactEmail')}else{alert("Por favor, preencha todos os campos obrigatórios (*).")}})}
export function renderHomeProjects(){const container=document.getElementById('projects-grid-container');if(!container)return;const featuredProjects=db.projects.slice(0,3);let html='';featuredProjects.forEach(project=>{html+=createProjectCard(project,!1)});container.innerHTML=html}
export function updateActiveNavLink(){const currentPath=window.location.pathname.split('?')[0];const navLinks=document.querySelectorAll('.nav-links > li > a.nav-link');navLinks.forEach(link=>{const linkPath=link.getAttribute('href');link.classList.remove('active');if(linkPath===currentPath){link.classList.add('active')}})}
export function renderAllProjects(){const container=document.getElementById('projects-grid-container');if(!container)return;let html='';db.projects.forEach(project=>{html+=createProjectCard(project,!0)});container.innerHTML=html;initFilter()}
export function renderTestimonials(){const container=document.getElementById('testimonials-grid-container');if(!container)return;let html='';db.testimonials.forEach(testimonial=>{html+=createTestimonialCard(testimonial)});container.innerHTML=html}
function applyTheme(theme){const body=document.body;const lightBtn=document.getElementById('theme-light');const darkBtn=document.getElementById('theme-dark');const contrastBtn=document.getElementById('theme-contrast');body.classList.remove('theme-dark','theme-high-contrast');if(lightBtn)lightBtn.classList.remove('active');if(darkBtn)darkBtn.classList.remove('active');if(contrastBtn)contrastBtn.classList.remove('active');if(theme==='dark'){body.classList.add('theme-dark');if(darkBtn)darkBtn.classList.add('active');localStorage.setItem('theme','dark')}else if(theme==='high-contrast'){body.classList.add('theme-high-contrast');if(contrastBtn)contrastBtn.classList.add('active');localStorage.setItem('theme','high-contrast')}else{if(lightBtn)lightBtn.classList.add('active');localStorage.setItem('theme','light')}}
export function initThemeSwitcher(){const lightBtn=document.getElementById('theme-light');const darkBtn=document.getElementById('theme-dark');const contrastBtn=document.getElementById('theme-contrast');if(lightBtn&&darkBtn&&contrastBtn){lightBtn.addEventListener('click',()=>applyTheme('light'));darkBtn.addEventListener('click',()=>applyTheme('dark'));contrastBtn.addEventListener('click',()=>applyTheme('high-contrast'))}}
export function applySavedTheme(){const savedTheme=localStorage.getItem('theme')||'light';applyTheme(savedTheme)}